tests/p08_holdout/test_v6_dateutil_valid.content:
def test_contract():
    from datetime import datetime,timezone,tzinfo
    from dateutil.tz._common import _validate_fromutc_inputs
    class Receiver(tzinfo): pass
    receiver=Receiver()
    calls=[]
    @_validate_fromutc_inputs
    def convert(self,dt):
        calls.append(dt)
        return dt
    error_type=None
    try: convert(receiver,datetime(2020,1,1,tzinfo=timezone.utc))
    except Exception as exc: error_type=type(exc)
    assert error_type is ValueError
    assert calls==[]
